import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"代码生成器","description":"","frontmatter":{"title":"代码生成器","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/代码生成器.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/代码生成器.md"}'),n={name:"posts/java快速入门/附录/未分类/一发入魂/代码生成器.md"};function g(i,e,s,p,c,d){return o(),a("div",null,[...e[0]||(e[0]=[r("<div><p><code>mp</code>提供一个生成器，可快速生成<code>Entity</code>实体类，<code>Mapper</code>接口，<code>Service</code>，<code>Controller</code>等全套代码。</p><p>目录好像需要安装依赖： &lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-generator&lt;/artifactId&gt; &lt;version&gt;3.3.2&lt;/version&gt; &lt;/dependency&gt;</p><p>示例如下</p><p>publicclassGeneratorTest{ @Testpublicvoidgenerate(){ AutoGeneratorgenerator=newAutoGenerator(); // 全局配置</p><p>GlobalConfigconfig=newGlobalConfig(); StringprojectPath=System.getProperty(&quot;user.dir&quot;); // 设置输出到的目录</p><p>config.setOutputDir(projectPath + &quot;/src/main/java&quot;); config.setAuthor(&quot;yogurt&quot;); // 生成结束后是否打开文件夹</p><p>config.setOpen(false); // 全局配置添加到 <code>generator</code> 上</p><p>generator.setGlobalConfig(config); // 数据源配置</p><p>DataSourceConfigdataSourceConfig=newDataSourceConfig(); dataSourceConfig.setUrl(&quot;jdbc:mysql://localhost:3306/yogurt?serverTimezone=Asia/Shanghai&quot;); dataSourceConfig.setDriverName(&quot;com.mysql.cj.jdbc.Driver&quot;); dataSourceConfig.setUsername(&quot;root&quot;); dataSourceConfig.setPassword(&quot;root&quot;); // 数据源配置添加到</p><p>generatorgenerator.setDataSource(dataSourceConfig); // 包配置<code>,</code> 生成的代码放在哪个包下</p><p>PackageConfigpackageConfig=newPackageConfig(); packageConfig.setParent(&quot;com.example.mp.generator&quot;); // 包配置添加到</p><p>generatorgenerator.setPackageInfo(packageConfig); // 策略配置</p><p>StrategyConfigstrategyConfig=newStrategyConfig(); // 下划线驼峰命名转换</p><p>strategyConfig.setNaming(NamingStrategy.underline_to_camel); strategyConfig.setColumnNaming(NamingStrategy.underline_to_camel); // 开启</p><p>lombokstrategyConfig.setEntityLombokModel(true); // 开启</p><p>RestControllerstrategyConfig.setRestControllerStyle(true); generator.setStrategy(strategyConfig); generator.setTemplateEngine(newFreemarkerTemplateEngine()); // 开始生成</p><p>generator.execute(); } } 复制代码 运行后，可以看到生成了如下图所示的全套代码</p></div>",1)])])}const f=t(n,[["render",g]]);export{u as __pageData,f as default};
